const staticData = $getWorkflowStaticData('global');
const gates = [
  { node: 'productionGateNewsAPI', label: 'NewsAPI', ok: (j) => j && j.status === 'ok' && !j.error },
  { node: 'productionGateAnthropic', label: 'Anthropic', ok: (j) => j && (Array.isArray(j.data) || j.model) && !j.error },
  { node: 'productionGateOpenAI', label: 'OpenAI', ok: (j) => j && (j.object === 'list' || Array.isArray(j.data)) && !j.error },
  { node: 'productionGateMeta', label: 'Meta', ok: (j) => j && j.data && j.data.is_valid === true && !j.error },
];
const failures = [];
for (const g of gates) {
  let healthy = false;
  let detail = 'not_executed';
  try {
    if ($(g.node).isExecuted) {
      const j = $(g.node).first().json;
      healthy = g.ok(j);
      detail = healthy ? 'ok' : JSON.stringify(j).slice(0, 300);
    }
  } catch (e) {
    detail = e.message;
  }
  if (!healthy) failures.push({ api: g.label, detail });
}
const allApisHealthy = failures.length === 0;
staticData.apisHealthy = allApisHealthy;
staticData.lastApiGateCheck = new Date().toISOString();
staticData.lastApiGateFailures = failures;
if (!allApisHealthy) {
  staticData.productionHalted = true;
  staticData.circuitBreakerHalted = true;
}
return [{
  json: {
    allApisHealthy,
    failures,
    failureSummary: failures.map(f => f.api + ': ' + f.detail).join('; '),
    haltReason: allApisHealthy ? null : 'PRODUCTION_COST_GUARD',
  }
}];

